mapper.select:
select sp.id,sp.sport_id,sp.region_id,sp.data_source_code,sp.player_manager_id,sp.third_player_id,sp.third_source_player_id,
       sp.picture_url,sp.name_code,sp.weight,sp.height,sp.gender,sp.birthday,sp.name_spell,sp.country_id,
       sp.personal_feature,sp.nick_name,sp.name,sp.related_data_source_coder_num,sp.related_data_source_coder_list,
       sp.remark,sp.create_time,sp.modify_time
from   standard_sport_player sp
where  sp.modify_time >= #{modifyTime}

    and sp.third_source_player_id = #{thirdSourcePlayerId}


    and sp.data_source_code = #{dataSourceCode}


    and sp.sport_id = #{thirdSportId}

select * from language_internation where 1=1

    and language_type in('en','zs') and  name_code in

        #{code}
